import{_ as i,c as t,o as e,a0 as a}from"./chunks/framework.oTSD2LDJ.js";const g=JSON.parse('{"title":"Official Plugins","description":"","frontmatter":{"title":"Official Plugins","editLink":true},"headers":[],"relativePath":"en/official-plugins.md","filePath":"en/official-plugins.md"}'),l={name:"en/official-plugins.md"};function o(s,n,r,d,u,p){return e(),t("div",null,n[0]||(n[0]=[a(`<h1 id="official-plugins" tabindex="-1">Official Plugins <a class="header-anchor" href="#official-plugins" aria-label="Permalink to &quot;Official Plugins&quot;">​</a></h1><p>The Uniquenium official plugin pack provides a set of commonly used component extensions covering system monitoring, network info, weather, calendar, and more. Installing official plugins gives your desktop a rich set of out-of-the-box components immediately.</p><h2 id="plugin-list" tabindex="-1">Plugin List <a class="header-anchor" href="#plugin-list" aria-label="Permalink to &quot;Plugin List&quot;">​</a></h2><p>The official plugin pack (<code>Uniquenium-Official-Plugins</code>) typically includes:</p><table tabindex="0"><thead><tr><th>Plugin</th><th>Components</th><th>Description</th></tr></thead><tbody><tr><td><strong>SystemMonitor</strong></td><td>CPUMonitor, MemoryMonitor, NetMonitor, BatteryMonitor</td><td>Real-time system monitoring</td></tr><tr><td><strong>Weather</strong></td><td>WeatherCard, WeatherForecast</td><td>Weather display (API key required)</td></tr><tr><td><strong>Calendar</strong></td><td>CalendarCard, ClockCard</td><td>Calendar and clock components</td></tr><tr><td><strong>Media</strong></td><td>MediaPlayer, VolumeControl</td><td>Media playback and volume control</td></tr><tr><td><strong>QuickNote</strong></td><td>NotePad, TodoList</td><td>Notes and todo list</td></tr></tbody></table><blockquote><p>The plugin list may change between versions. Refer to the official repository for the latest list.</p></blockquote><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="option-1-using-the-installer-recommended" tabindex="-1">Option 1: Using the installer (recommended) <a class="header-anchor" href="#option-1-using-the-installer-recommended" aria-label="Permalink to &quot;Option 1: Using the installer (recommended)&quot;">​</a></h3><ol><li>Download <code>Uniquenium-Plugins-Setup-*.exe</code> from the releases page</li><li>Run the installer and select the Uniquenium installation directory</li><li>After installation, plugins are automatically placed in the <code>plugins/</code> directory</li><li>Launch Uniquenium and check installed plugins under <strong>Settings → Plugins</strong></li></ol><h3 id="option-2-manual-installation" tabindex="-1">Option 2: Manual installation <a class="header-anchor" href="#option-2-manual-installation" aria-label="Permalink to &quot;Option 2: Manual installation&quot;">​</a></h3><ol><li>Download the latest release from the <a href="https://github.com/Uniquenium/Official-Plugins" target="_blank" rel="noreferrer">Official Plugins repository</a></li><li>Extract the DLL files into subfolders under <code>&lt;Uniquenium install dir&gt;/plugins/</code></li><li>Launch Uniquenium; plugins are auto-scanned and loaded</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Uniquenium/</span></span>
<span class="line"><span>├── Uniquenium.exe</span></span>
<span class="line"><span>├── plugins/</span></span>
<span class="line"><span>│   ├── SystemMonitor/</span></span>
<span class="line"><span>│   │   └── SystemMonitor.dll</span></span>
<span class="line"><span>│   ├── Weather/</span></span>
<span class="line"><span>│   │   └── Weather.dll</span></span>
<span class="line"><span>│   └── Calendar/</span></span>
<span class="line"><span>│       └── Calendar.dll</span></span></code></pre></div><h3 id="option-3-in-app-installation" tabindex="-1">Option 3: In-app installation <a class="header-anchor" href="#option-3-in-app-installation" aria-label="Permalink to &quot;Option 3: In-app installation&quot;">​</a></h3><ol><li>Open Uniquenium Settings</li><li>Go to the <strong>Plugins</strong> tab</li><li>Click <strong>Install from local</strong> to select a downloaded plugin pack</li><li>Or click <strong>Check for updates</strong> to fetch the latest plugins from the remote repository</li></ol><h2 id="configuring-plugins" tabindex="-1">Configuring Plugins <a class="header-anchor" href="#configuring-plugins" aria-label="Permalink to &quot;Configuring Plugins&quot;">​</a></h2><p>Some plugins require additional configuration. Taking the Weather plugin as an example:</p><ol><li>Open the component editor and drag a <code>WeatherCard</code> from the plugin category</li><li>Right-click the component → <strong>Properties</strong> → fill in the API key and city</li><li>Or configure it globally under the <strong>Plugins</strong> tab in Settings</li></ol><h2 id="uninstalling-plugins" tabindex="-1">Uninstalling Plugins <a class="header-anchor" href="#uninstalling-plugins" aria-label="Permalink to &quot;Uninstalling Plugins&quot;">​</a></h2><ol><li>Open <strong>Settings → Plugins</strong></li><li>Find the plugin to remove</li><li>Click the <strong>Uninstall</strong> button</li><li>Or directly delete the corresponding subfolder under <code>plugins/</code></li></ol><h2 id="developing-plugins" tabindex="-1">Developing Plugins <a class="header-anchor" href="#developing-plugins" aria-label="Permalink to &quot;Developing Plugins&quot;">​</a></h2><p>If you want to develop your own plugins, refer to the <a href="./custom-developing/plugin">Plugin Development Guide</a> and <a href="./controls-reference/cpp-ext/UniDeskPluginInterface">UniDeskPluginInterface</a>.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The official plugins must match the major version of the Uniquenium main program.</li><li>A plugin that fails to load at runtime does not affect the stability of the main program; the system skips the failed plugin and continues loading others.</li><li>Install third-party plugins only from trusted sources.</li></ul>`,23)]))}const h=i(l,[["render",o]]);export{g as __pageData,h as default};
